<style>
  :root {
    --green: #2D6A4F;
    --green-dark: #1B4332;
    --green-light: #40916C;
    --accent: #F4A261;
    --accent-dark: #E76F51;
    --cream: #FEFAE0;
    --cream-dark: #FAEDCD;
    --warm-white: #FFFAF0;
    --text-primary: #2D2D2D;
    --text-secondary: #5C5C5C;
    --text-muted: #8B8B8B;
    --border: #E8DDD0;
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
    background: var(--cream);
    color: var(--text-primary);
    margin: 0;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }
  h1, h2, h3, h4, .font-heading {
    font-family: 'Nunito', system-ui, -apple-system, sans-serif;
  }

  /* Header */
  .header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(254, 250, 224, 0.92);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
  }
  .header-inner {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 4rem;
  }
  .logo {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 1.5rem;
    color: var(--green);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    text-decoration: none;
  }
  .logo-icon {
    width: 2rem;
    height: 2rem;
    background: var(--green);
    border-radius: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 1.1rem;
  }
  .nav-links {
    display: flex;
    align-items: center;
    gap: 2rem;
    list-style: none;
    margin: 0;
    padding: 0;
  }
  .nav-links a {
    text-decoration: none;
    color: var(--text-primary);
    font-weight: 500;
    font-size: 0.95rem;
    transition: color 0.2s;
    position: relative;
  }
  .nav-links a:hover { color: var(--green); }
  .nav-links a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--accent);
    border-radius: 1px;
    transition: width 0.2s ease;
  }
  .nav-links a:hover::after { width: 100%; }
  .mobile-menu-btn {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    color: var(--text-primary);
  }

  /* Sections */
  .section {
    padding: 5rem 1.5rem;
  }
  .section-inner {
    max-width: 1280px;
    margin: 0 auto;
  }
  .section-label {
    display: inline-block;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 0.75rem;
  }
  .section-title {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 2.5rem;
    color: var(--green-dark);
    margin: 0 0 1rem 0;
    line-height: 1.2;
  }
  .section-subtitle {
    color: var(--text-secondary);
    font-size: 1.15rem;
    margin: 0 0 2.5rem 0;
    max-width: 600px;
  }

  /* Hero */
  .hero {
    position: relative;
    background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 50%, var(--green-light) 100%);
    color: white;
    padding: 6rem 1.5rem;
    overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(circle at 20% 50%, rgba(244, 162, 97, 0.15) 0%, transparent 50%),
      radial-gradient(circle at 80% 20%, rgba(254, 250, 224, 0.08) 0%, transparent 40%);
