  }
  .hero-pattern {
    position: absolute;
    inset: 0;
    opacity: 0.06;
    background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M30 10a5 5 0 1 1 0-10 5 5 0 0 1 0 10zm0 50a5 5 0 1 1 0-10 5 5 0 0 1 0 10zM10 30a5 5 0 1 1 0-10 5 5 0 0 1 0 10zm40 0a5 5 0 1 1 0-10 5 5 0 0 1 0 10z' fill='white'/%3E%3C/svg%3E");
    pointer-events: none;
  }
  .hero-inner {
    max-width: 1280px;
    margin: 0 auto;
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
  }
  .hero-content h1 {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 3.5rem;
    line-height: 1.15;
    margin: 0 0 1.25rem 0;
  }
  .hero-content p {
    font-size: 1.2rem;
    line-height: 1.7;
    opacity: 0.92;
    margin: 0 0 2rem 0;
    max-width: 520px;
  }
  .hero-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
  }
  .btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.85rem 1.75rem;
    border-radius: 3rem;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1rem;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.2s ease;
    border: none;
  }
  .btn-primary {
    background: var(--accent);
    color: var(--text-primary);
  }
  .btn-primary:hover {
    background: var(--accent-dark);
    color: white;
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(231, 111, 81, 0.3);
  }
  .btn-outline {
    background: transparent;
    color: white;
    border: 2px solid rgba(255,255,255,0.4);
  }
  .btn-outline:hover {
    background: rgba(255,255,255,0.12);
    border-color: white;
    transform: translateY(-2px);
  }
  .hero-visual {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .hero-image-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 1fr 1fr;
    gap: 0.75rem;
    width: 100%;
    max-width: 480px;
  }
  .hero-image-grid .img-card {
    border-radius: 1rem;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    aspect-ratio: 4/3;
    background: rgba(255,255,255,0.1);
  }
  .hero-image-grid .img-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
  }
  .hero-image-grid .img-card:hover img { transform: scale(1.05); }
  .hero-image-grid .img-card:nth-child(1) { border-radius: 2rem 1rem 0.5rem 1rem; }
  .hero-image-grid .img-card:nth-child(2) { border-radius: 1rem 2rem 1rem 0.5rem; }
  .hero-image-grid .img-card:nth-child(3) { border-radius: 1rem 0.5rem 1rem 2rem; }
  .hero-image-grid .img-card:nth-child(4) { border-radius: 0.5rem 1rem 2rem 1rem; }

  /* Brand Highlights */
  .highlights {
    background: white;
    padding: 3rem 1.5rem;
    border-bottom: 1px solid var(--border);
  }
  .highlights-inner {
    max-width: 1280px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
  }
  .highlight-item {
    text-align: center;
    padding: 1.5rem;
  }
  .highlight-number {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 2.75rem;
    color: var(--green);
    line-height: 1;
  }
  .highlight-label {
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1.05rem;
    color: var(--text-primary);
    margin: 0.5rem 0 0.35rem 0;
  }
  .highlight-desc {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin: 0;
  }

  /* Featured Products Carousel */
  .carousel-wrapper {
    position: relative;
  }
  .carousel {
    display: flex;
    gap: 1.25rem;
    overflow-x: auto;
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
    padding: 0.5rem 0 1rem 0;
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
  .carousel::-webkit-scrollbar { display: none; }
  .product-card {
    flex: 0 0 260px;
    scroll-snap-align: start;
    background: white;
    border-radius: 1.25rem;
    overflow: hidden;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    transition: all 0.3s ease;
    cursor: pointer;
  }
  .product-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 12px 32px rgba(0,0,0,0.1);
  }
  .product-card-img {
    height: 200px;
    background: var(--cream-dark);
    overflow: hidden;
  }
  .product-card-img img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
  }
  .product-card:hover .product-card-img img { transform: scale(1.06); }
  .product-card-body {
    padding: 1.25rem;
  }
  .product-card-body h3 {
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1.1rem;
    margin: 0 0 0.35rem 0;
    color: var(--text-primary);
  }
  .product-card-body .desc {
    font-size: 0.88rem;
    color: var(--text-secondary);
    margin: 0 0 0.75rem 0;
    line-height: 1.5;
  }
  .product-card-body .price {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 1.25rem;
    color: var(--green);
  }
  .carousel-controls {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
  }
  .carousel-btn {
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 50%;
    border: 2px solid var(--border);
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    color: var(--text-primary);
  }
  .carousel-btn:hover {
    background: var(--green);
    border-color: var(--green);
    color: white;
  }

  /* Seasonal Picks */
  .seasonal {
    background: linear-gradient(180deg, var(--cream) 0%, white 100%);
  }
  .seasonal-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
  }
  .seasonal-card {
    background: white;
    border-radius: 1.25rem;
    overflow: hidden;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    transition: all 0.3s ease;
    border: 2px solid transparent;
  }
  .seasonal-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(0,0,0,0.1);
    border-color: var(--accent);
  }
  .seasonal-card-img {
    height: 180px;
    background: var(--cream-dark);
    overflow: hidden;
    position: relative;
  }
  .seasonal-card-img img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
  }
  .seasonal-card:hover .seasonal-card-img img { transform: scale(1.06); }
  .seasonal-badge {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    background: var(--accent);
    color: white;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 0.75rem;
    padding: 0.3rem 0.75rem;
    border-radius: 2rem;
  }
  .seasonal-card-body {
    padding: 1.25rem;
  }
  .seasonal-card-body h3 {
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1rem;
    margin: 0 0 0.35rem 0;
  }
  .seasonal-card-body p {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin: 0 0 0.75rem 0;
  }
  .seasonal-card-body .price {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 1.2rem;
    color: var(--green);
  }

  /* Categories */
  .categories-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1.25rem;
  }
  .category-card {
    position: relative;
    border-radius: 1.25rem;
    overflow: hidden;
    aspect-ratio: 1;
    cursor: pointer;
    background: var(--cream-dark);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
  }
  .category-card:hover {
    transform: scale(1.04);
    box-shadow: 0 16px 40px rgba(0,0,0,0.12);
  }
  .category-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
  }
  .category-card:hover img { transform: scale(1.08); }
  .category-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(27, 67, 50, 0.1) 0%, rgba(27, 67, 50, 0.75) 70%);
    display: flex;
    align-items: flex-end;
    padding: 1.25rem;
    transition: background 0.3s ease;
  }
  .category-card:hover .category-overlay {
    background: linear-gradient(180deg, rgba(27, 67, 50, 0.2) 0%, rgba(27, 67, 50, 0.85) 70%);
  }
  .category-overlay h3 {
    font-family: 'Nunito', sans-serif;
    font-weight: 800;
    font-size: 1.25rem;
    color: white;
    margin: 0;
    text-shadow: 0 2px 8px rgba(0,0,0,0.3);
  }
  .category-tagline {
    font-size: 0.82rem;
    color: rgba(255,255,255,0.85);
    margin: 0.25rem 0 0 0;
  }

  /* Store Locator */
  .store-locator {
    background: white;
  }
  .locator-form {
    display: flex;
    gap: 0.75rem;
    max-width: 480px;
    margin-bottom: 2rem;
  }
  .locator-form input {
    flex: 1;
    padding: 0.85rem 1.25rem;
    border: 2px solid var(--border);
    border-radius: 3rem;
    font-family: 'Inter', sans-serif;
    font-size: 1rem;
    outline: none;
    transition: border-color 0.2s;
  }
  .locator-form input:focus { border-color: var(--green); }
  .locator-form input::placeholder { color: var(--text-muted); }
  .store-results {
    display: none;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
  }
  .store-results.visible { display: grid; }
  .store-card {
    background: var(--warm-white);
    border-radius: 1.25rem;
    padding: 1.5rem;
    border: 1px solid var(--border);
    transition: all 0.3s ease;
  }
  .store-card:hover {
    box-shadow: 0 8px 24px rgba(0,0,0,0.08);
    border-color: var(--accent);
  }
  .store-card h3 {
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1.1rem;
    margin: 0 0 0.5rem 0;
    color: var(--green-dark);
  }
  .store-card .address {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin: 0 0 0.75rem 0;
    line-height: 1.5;
  }
  .store-card .meta {
    display: flex;
    gap: 1rem;
    font-size: 0.85rem;
    color: var(--text-muted);
  }
  .store-card .meta span {
    display: flex;
    align-items: center;
    gap: 0.3rem;
  }
  .store-card .distance {
    display: inline-block;
    background: var(--green);
    color: white;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 0.8rem;
    padding: 0.2rem 0.75rem;
    border-radius: 2rem;
    margin-top: 0.75rem;
  }

  /* Newsletter */
  .newsletter {
    background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 100%);
    color: white;
    text-align: center;
    padding: 5rem 1.5rem;
  }
  .newsletter .section-title { color: white; }
  .newsletter .section-subtitle { color: rgba(255,255,255,0.8); margin-left: auto; margin-right: auto; }
  .newsletter-form {
    display: flex;
    gap: 0.75rem;
    max-width: 480px;
    margin: 0 auto;
  }
  .newsletter-form input {
    flex: 1;
    padding: 0.85rem 1.25rem;
    border: 2px solid rgba(255,255,255,0.3);
    border-radius: 3rem;
    background: rgba(255,255,255,0.1);
    color: white;
    font-family: 'Inter', sans-serif;
    font-size: 1rem;
    outline: none;
  }
  .newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
  .newsletter-form input:focus { border-color: var(--accent); background: rgba(255,255,255,0.15); }
  .newsletter-form .btn-subscribe {
    background: var(--accent);
    color: var(--text-primary);
    border: none;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1rem;
    padding: 0.85rem 1.75rem;
    border-radius: 3rem;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
  }
  .newsletter-form .btn-subscribe:hover {
    background: #F5B041;
    transform: translateY(-2px);
  }
  .newsletter-confirmation {
    display: none;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 1rem;
    padding: 1.25rem 2rem;
    margin-top: 1.5rem;
    font-weight: 500;
    max-width: 480px;
    margin-left: auto;
    margin-right: auto;
  }
  .newsletter-confirmation.visible { display: block; }

  /* Footer */
  .footer {
    background: var(--green-dark);
    color: rgba(255,255,255,0.8);
    padding: 4rem 1.5rem 2rem;
  }
  .footer-inner {
    max-width: 1280px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
    gap: 2rem;
  }
  .footer-brand .logo { color: white; }
  .footer-brand p {
    font-size: 0.9rem;
    margin: 1rem 0 0 0;
    opacity: 0.7;
    max-width: 280px;
    line-height: 1.7;
  }
  .footer h4 {
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1rem;
    color: white;
    margin: 0 0 1rem 0;
  }
  .footer ul {
    list-style: none;
    padding: 0;
    margin: 0;
  }
  .footer ul li { margin-bottom: 0.6rem; }
  .footer ul li a {
    color: rgba(255,255,255,0.65);
    text-decoration: none;
    font-size: 0.9rem;
    transition: color 0.2s;
  }
  .footer ul li a:hover { color: var(--accent); }
  .footer-bottom {
    max-width: 1280px;
    margin: 3rem auto 0;
    padding-top: 1.5rem;
    border-top: 1px solid rgba(255,255,255,0.1);
    text-align: center;
    font-size: 0.85rem;
    opacity: 0.6;
  }

  /* Mobile nav */
  .mobile-menu {
    display: none;
    position: fixed;
    inset: 0;
    background: var(--cream);
    z-index: 100;
    padding: 5rem 1.5rem 2rem;
  }
  .mobile-menu.active { display: flex; flex-direction: column; gap: 0.5rem; }
  .mobile-menu a {
    display: block;
    padding: 1rem 0;
    font-family: 'Nunito', sans-serif;
    font-weight: 700;
    font-size: 1.25rem;
    color: var(--text-primary);
    text-decoration: none;
    border-bottom: 1px solid var(--border);
  }
  .mobile-menu-close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    color: var(--text-primary);
  }

  @media (max-width: 1024px) {
    .hero-inner { grid-template-columns: 1fr; }
    .hero-visual { order: -1; }
    .hero-image-grid { max-width: 400px; }
    .hero-content h1 { font-size: 2.5rem; }
    .section-title { font-size: 2rem; }
    .highlights-inner { grid-template-columns: repeat(2, 1fr); }
    .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
    .categories-grid { grid-template-columns: repeat(3, 1fr); }
    .store-results { grid-template-columns: repeat(2, 1fr); }
    .footer-inner { grid-template-columns: 1fr 1fr 1fr; }
    .footer-brand { grid-column: 1 / -1; }
  }

  @media (max-width: 768px) {
    .nav-links { display: none; }
    .mobile-menu-btn { display: block; }
    .hero { padding: 4rem 1.25rem; }
    .hero-content h1 { font-size: 2rem; }
    .hero-image-grid { max-width: 300px; }
    .section { padding: 3rem 1.25rem; }
    .section-title { font-size: 1.75rem; }
    .product-card { flex: 0 0 220px; }
    .highlights-inner { grid-template-columns: 1fr 1fr; gap: 1rem; }
    .highlight-number { font-size: 2rem; }
