<script>
// Initialize Lucide icons
lucide.createIcons();

// Mobile menu
function toggleMobileMenu() {
  document.getElementById('mobileMenu').classList.toggle('active');
}

// Carousel scroll
function scrollCarousel(direction) {
  var carousel = document.getElementById('productCarousel');
  var cardWidth = carousel.querySelector('.product-card').offsetWidth;
  var gap = 20; // 1.25rem gap
  var scrollAmount = (cardWidth + gap) * 2;
  carousel.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
}

// Store locator search
function searchStores(event) {
  event.preventDefault();
  var input = document.getElementById('zipInput');
  var results = document.getElementById('storeResults');
  if (input.value.trim().length >= 3) {
    results.classList.add('visible');
    lucide.createIcons();
  }
}

// Newsletter subscription
function subscribeNewsletter(event) {
  event.preventDefault();
  var confirm = document.getElementById('newsletterConfirm');
  var input = document.getElementById('emailInput');
  if (input.value.trim()) {
    confirm.classList.add('visible');
    input.value = '';
    setTimeout(function() {
      confirm.classList.remove('visible');
    }, 5000);
  }
}
</script>
